values (md5('PE-018:policy:dress_socks:6')::uuid, 'PE-018', 'https://www.dinoville.ca/rules', '2026-11-07', 'verified', null, 'dress_socks', 'Kids and their parents or guardians must wear socks inside the playground. Forgot yours? Socks are $2 a pair at the front desk.', 6);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:arrival:7')::uuid, 'PE-018', 'https://www.dinoville.ca/faq', '2026-11-07', 'verified', null, 'arrival', 'Strollers are allowed only in the dining area, not near the play structures.', 7);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:food_rule:8')::uuid, 'PE-018', 'https://www.dinoville.ca/rules', '2026-11-07', 'verified', null, 'food_rule', 'No food or drinks in or around the play structures, even during private parties. No foods containing nuts.', 8);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:restriction:9')::uuid, 'PE-018', 'https://www.dinoville.ca/rules', '2026-11-07', 'verified', null, 'restriction', 'No outside toys or sharp objects, no confetti, silly string or glitter, and no vaping, smoking or alcohol.', 9);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:other:10')::uuid, 'PE-018', 'https://www.dinoville.ca/faq', '2026-11-07', 'verified', null, 'other', 'No memberships or loyalty programs.', 10);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:other:11')::uuid, 'PE-018', 'https://www.dinoville.ca/faq', '2026-11-07', 'verified', null, 'other', 'There''s no lost and found, so check for your belongings before you leave.', 11);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:party:12')::uuid, 'PE-018', 'https://www.dinoville.ca/home-2852-1557-5511-2478', '2026-11-07', 'verified', null, 'party', 'A private party closes the entire playground to other guests for 2 hours. Hosts bring their own food, cutlery, non-alcoholic drinks and decorations. Holidays are priced like weekends.', 12);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:party:13')::uuid, 'PE-018', 'https://www.dinoville.ca/faq', '2026-11-07', 'verified', null, 'party', 'The $100 deposit is due within 24 hours of choosing a date and time; the balance is due on the party day. Babies under 1 and the birthday child don''t count toward the kids'' headcount; hosting parents count as adults.', 13);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-018:policy:party:14')::uuid, 'PE-018', 'https://www.dinoville.ca/faq', '2026-11-07', 'verified', null, 'party', 'Not allowed at parties: electric appliances (microwaves, kettles, coffee machines, crockpots, food warmers, hot plates), flame-heated chafing dishes, and bubble shows.', 14);

